import java.util.*;

public class Main {
    static final int MOD = 1000000007;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int w = scanner.nextInt();
        int h = scanner.nextInt();
        scanner.close();

        // Number of points with (x%2, y%2)
        long[] cnt = new long[4];
        for (int x = 0; x <= w; x++) {
            for (int y = 0; y <= h; y++) {
                int idx = ((x & 1) << 1) | (y & 1);
                cnt[idx]++;
            }
        }

        // Total ordered triples of distinct points
        long totalPoints = (long) (w + 1) * (h + 1);
        long totalOrdered = totalPoints * (totalPoints - 1) % MOD * (totalPoints - 2) % MOD;

        // Count triples with even doubled area (S even)
        long evenOrdered = 0;
        // Parity coordinates
        int[] px = {0, 0, 1, 1};
        int[] py = {0, 1, 0, 1};
        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < 4; j++) {
                for (int k = 0; k < 4; k++) {
                    // Compute S = x1(y2 - y3) + x2(y3 - y1) + x3(y1 - y2) mod 2
                    int S = (px[i] * (py[j] - py[k]) + px[j] * (py[k] - py[i]) + px[k] * (py[i] - py[j])) & 1;
                    if (S == 0) {
                        long ways;
                        if (i == j && j == k) {
                            ways = cnt[i] * (cnt[i] - 1) % MOD * (cnt[i] - 2) % MOD;
                        } else if (i == j) {
                            ways = cnt[i] * (cnt[i] - 1) % MOD * cnt[k] % MOD;
                        } else if (i == k) {
                            ways = cnt[i] * (cnt[i] - 1) % MOD * cnt[j] % MOD;
                        } else if (j == k) {
                            ways = cnt[j] * (cnt[j] - 1) % MOD * cnt[i] % MOD;
                        } else {
                            ways = cnt[i] * cnt[j] % MOD * cnt[k] % MOD;
                        }
                        evenOrdered = (evenOrdered + ways) % MOD;
                    }
                }
            }
        }

        // Count collinear ordered triples (distinct points)
        // Horizontal
        long collinear = 0;
        if (w >= 2) {
            collinear = (collinear + (long) (h + 1) * (w + 1) % MOD * w % MOD * (w - 1)) % MOD;
        }
        // Vertical
        if (h >= 2) {
            collinear = (collinear + (long) (w + 1) * (h + 1) % MOD * h % MOD * (h - 1)) % MOD;
        }
        // Diagonal (non-axis-aligned)
        for (int dx = 1; dx <= w; dx++) {
            for (int dy = 1; dy <= h; dy++) {
                int g = gcd(dx, dy);
                if (g >= 2) {
                    long lines = (long) (w - dx + 1) * (h - dy + 1) % MOD;
                    long add = lines * (g - 1) % MOD * 2 % MOD;
                    collinear = (collinear + add) % MOD;
                }
            }
        }

        long ans = (evenOrdered - collinear) % MOD;
        if (ans < 0) ans += MOD;
        System.out.println(ans);
    }

    static int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}
